package com.kologeski.interviewassistant.candidate;
import com.kologeski.interviewassistant.api.ResourceNotFoundException; import com.kologeski.interviewassistant.audit.*; import com.kologeski.interviewassistant.company.*; import org.slf4j.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class CandidateService {
 private static final Logger log=LoggerFactory.getLogger(CandidateService.class);
 private final CandidateRepository candidates; private final CandidateVacancyRepository links; private final CandidateTimelineRepository events; private final CompanyAuthorizationPolicy authorization; private final AuditTrailService audit; private final Clock clock;
 public CandidateService(CandidateRepository c,CandidateVacancyRepository l,CandidateTimelineRepository e,CompanyAuthorizationPolicy a,AuditTrailService audit,Clock clock){candidates=c;links=l;events=e;authorization=a;this.audit=audit;this.clock=clock;}
 @Transactional public Candidate resolve(UUID company,UUID vacancy,String name,String actor){String normalized=Candidate.normalize(name);var now=Instant.now(clock);var existing=candidates.findByCompanyIdAndNormalizedName(company,normalized);Candidate candidate=existing.orElseGet(()->candidates.saveAndFlush(new Candidate(company,name,actor,now)));if(existing.isEmpty()){events.save(new CandidateTimelineEvent(company,candidate.id(),"CANDIDATE_CREATED",vacancy,null,now,actor));audit.record(company,Long.valueOf(actor),"DOMAIN","CANDIDATE_CREATED","CANDIDATE",candidate.id());log.info("metric=candidate_created companyId={} candidateId={}",company,candidate.id());}var link=links.findByCandidateIdAndVacancyId(candidate.id(),vacancy);if(link.isPresent())link.get().touch(now);else links.save(new CandidateVacancyLink(company,candidate.id(),vacancy,now));return candidate;}
 @Transactional public void interviewEvent(InterviewEvent event,UUID company,UUID candidate,UUID vacancy,UUID interview,String actor){events.save(new CandidateTimelineEvent(company,candidate,event.name(),vacancy,interview,Instant.now(clock),actor));audit.record(company,Long.valueOf(actor),"DOMAIN","TIMELINE_EVENT_CREATED","CANDIDATE",candidate);log.info("metric=timeline_event_created companyId={} candidateId={} eventType={}",company,candidate,event);}
 @Transactional(readOnly=true) public Page<CandidateView> list(String query,Pageable pageable){var active=authorization.require(CompanyCapability.VIEW_INTERVIEWS);String normalized=query==null||query.isBlank()?"":Candidate.normalize(query);return candidates.search(active.companyId(),normalized,pageable).map(CandidateView::from);}
 @Transactional(readOnly=true) public CandidateDetail get(UUID id){var active=authorization.require(CompanyCapability.VIEW_INTERVIEWS);var candidate=candidates.findByIdAndCompanyId(id,active.companyId()).orElseThrow(()->new ResourceNotFoundException("Candidato não encontrado."));return new CandidateDetail(CandidateView.from(candidate),events.findByCompanyIdAndCandidateIdOrderByOccurredAtDesc(active.companyId(),id).stream().map(TimelineView::from).toList());}
 public enum InterviewEvent{INTERVIEW_STARTED,INTERVIEW_COMPLETED} public record CandidateView(UUID id,String name,Instant createdAt){static CandidateView from(Candidate c){return new CandidateView(c.id(),c.displayName(),c.createdAt());}} public record TimelineView(UUID id,String type,UUID vacancyId,UUID interviewId,Instant occurredAt){static TimelineView from(CandidateTimelineEvent e){return new TimelineView(e.id(),e.eventType(),e.vacancyId(),e.interviewId(),e.occurredAt());}} public record CandidateDetail(CandidateView candidate,List<TimelineView> timeline){}
}
